#include <stdbool.h>
#include <stddef.h>

enum { CAP = 3 };
typedef struct { int data[CAP]; size_t count; } Stack;

static bool push(Stack *s, int value) {
    if (s->count == CAP) return false;
    s->data[s->count] = value;
    ++s->count;
    return true;
}

static bool pop(Stack *s, int *out) {
    if (s->count == 0) return false;
    --s->count;
    *out = s->data[s->count];
    return true;
}

int main(void) {
    Stack s = {{0}, 0};
    int value;
    if (!push(&s, 3)) return 1;
    if (!push(&s, 8)) return 1;
    if (!pop(&s, &value)) return 1;
    if (!push(&s, 5)) return 1;
    return 0;
}

#include <stdbool.h>
#include <stddef.h>

enum { CAP = 3 };
typedef struct { int data[CAP]; size_t count; } Stack;

static bool push(Stack *s, int value) {
    if (s->count == CAP) return false;
    s->data[s->count] = value;
    ++s->count;
    return true;
}

static bool pop(Stack *s, int *out) {
    if (s->count == 0) return false;
    --s->count;
    *out = s->data[s->count];
    return true;
}

int main(void) {
    Stack s = {{0}, 0};
    int value;
    if (!push(&s, -4)) return 1;
    if (!push(&s, 6)) return 1;
    if (!push(&s, 2)) return 1;
    if (!pop(&s, &value)) return 1;
    if (!push(&s, 9)) return 1;
    if (!pop(&s, &value)) return 1;
    if (!pop(&s, &value)) return 1;
    return 0;
}
